{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C25"],
      "claim": "Melperone, the closest analogue sharing the 4-fluorobutyrophenone and piperidine core, had an absolute oral bioavailability of 67 ± 28% in healthy volunteers, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C50"],
      "claim": "Haloperidol, a close butyrophenone analogue with the same 4-fluorobutyrophenone acyl chain, showed an absolute oral bioavailability of 0.70 ± 0.18 in humans, supporting high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C36"],
      "claim": "Bromperidol, another close haloperidol-type analogue, had an oral bioavailability of 30% in humans, still above the 20% threshold and supporting a high prediction.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "Ketanserin, which shares the 4-fluorobenzoyl-piperidine connectivity, had an absolute bioavailability of 50.4 ± 6.2% in healthy subjects, supporting high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Lumateperone had a very low absolute bioavailability of 4.4%, providing contradictory low-F evidence, but its fused polycyclic scaffold and distinct metabolic profile limit transferability to the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a benperidol-like 4-fluorobutyrophenone with a benzimidazolone-substituted piperidine. The closest and multiple butyrophenone analogues (melperone, haloperidol, bromperidol) consistently show absolute oral bioavailability values of 30–70%, all above the 20% threshold. The low-F example lumateperone is structurally distinct and outweighed by the convergent high-F evidence. Therefore, the query is predicted to have high oral bioavailability.",
  "evidence_gaps": [
    "No direct human absolute bioavailability record for the query molecule itself.",
    "No intravenous pharmacokinetic data for the query are available.",
    "Low-F analogues have lower structural similarity and different metabolic liabilities.",
    "Possible first-pass metabolism differences due to the benzimidazolone moiety are not directly measured."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

